import React from 'react';

function Header() {
  return (
    <header className="header">
      <img
        src="https://upload.wikimedia.org/wikipedia/commons/1/19/Spotify_logo_without_text.svg"
        alt="Spotify Logo"
        className="logo"
      />
      <h1>Mornyfy</h1>
    </header>
  );
}

export default Header;
